/* 1. Base Resets & Variables */
:root {
	--primary-color: #222222;
	--secondary-color: #555555;
	--accent-color: #0066cc;
	--bg-color: #fcfcfc;
	--card-bg: #ffffff;
	--border-color: #eaeaea;
	--font-stack:
		-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial,
		sans-serif;
}

* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

body {
	font-family: var(--font-stack);
	background-color: var(--bg-color);
	color: var(--primary-color);
	line-height: 1.6;
	font-size: 16px;
}

a {
	color: var(--accent-color);
	text-decoration: none;
}

a:hover {
	text-decoration: underline;
}

.container {
	max-width: 1100px;
	margin: 0 auto;
	padding: 0 20px;
}

/* 2. Header & Navigation */
.blog-header {
	background-color: var(--card-bg);
	padding: 40px 0 20px 0;
	text-align: center;
}

.blog-title {
	font-size: 2.5rem;
	font-weight: 700;
	letter-spacing: -1px;
}

.blog-tagline {
	color: var(--secondary-color);
	margin-top: 5px;
	font-size: 1.1rem;
}

.blog-nav {
	background-color: var(--card-bg);
	border-top: 1px solid var(--border-color);
	border-bottom: 1px solid var(--border-color);
	padding: 12px 0;
	position: sticky;
	top: 0;
	z-index: 100;
}

.blog-nav a {
	color: var(--primary-color);
	font-weight: 500;
	margin-right: 20px;
}

.blog-nav a:hover {
	color: var(--accent-color);
	text-decoration: none;
}

/* 3. Main Two-Column Layout */
.main-layout {
	display: grid;
	grid-template-columns: 2fr 1fr;
	gap: 40px;
	margin-top: 40px;
	margin-bottom: 60px;
}

/* 4. Blog Posts Feed */
.blog-main {
	display: flex;
	flex-direction: column;
	gap: 40px;
}

.blog-post {
	background-color: var(--card-bg);
	padding: 30px;
	border: 1px solid var(--border-color);
	border-radius: 6px;
}

.post-meta {
	font-size: 0.85rem;
	color: var(--secondary-color);
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.post-title {
	margin: 10px 0 15px 0;
	font-size: 1.75rem;
	line-height: 1.3;
}

.post-title a {
	color: var(--primary-color);
}

.post-title a:hover {
	color: var(--accent-color);
	text-decoration: none;
}

.post-excerpt {
	color: #444444;
	margin-bottom: 20px;
}

.read-more {
	font-weight: 600;
}

/* 5. Sidebar Widgets */
.blog-sidebar {
	display: flex;
	flex-direction: column;
	gap: 30px;
}

.sidebar-widget {
	background-color: var(--card-bg);
	padding: 24px;
	border: 1px solid var(--border-color);
	border-radius: 6px;
}

.sidebar-widget h3 {
	margin-bottom: 15px;
	font-size: 1.2rem;
	border-bottom: 2px solid var(--primary-color);
	padding-bottom: 5px;
	display: inline-block;
}

.sidebar-widget ul {
	list-style: none;
}

.sidebar-widget li {
	margin-bottom: 10px;
}

.sidebar-widget li a {
	color: var(--secondary-color);
}

.sidebar-widget li a:hover {
	color: var(--accent-color);
}

/* 6. Footer */
.blog-footer {
	background-color: var(--primary-color);
	color: #ffffff;
	text-align: center;
	padding: 30px 0;
	font-size: 0.9rem;
}

/* 7. Responsive Layout (Mobile view) */
@media (max-width: 768px) {
	.main-layout {
		grid-template-columns: 1fr;
		gap: 30px;
	}

	.blog-title {
		font-size: 2rem;
	}
}

/* 8. Single Article View Specific Styles */
.single-article-layout {
	max-width: 800px; /* Centered, highly readable line lengths for long-form reading */
	margin: 40px auto 60px auto;
	padding: 0 20px;
}

.blog-content {
	background-color: var(--card-bg);
	padding: 40px;
	border: 1px solid var(--border-color);
	border-radius: 6px;
}

.article-header {
	border-bottom: 1px solid var(--border-color);
	padding-bottom: 20px;
	margin-bottom: 30px;
}

.entry-title {
	font-size: 2.5rem;
	line-height: 1.2;
	margin-top: 10px;
	color: var(--primary-color);
}

/* Typography styles for the reading pane */
.article-body p {
	margin-bottom: 20px;
	color: #333333;
	font-size: 1.1rem;
}

.article-body h3 {
	font-size: 1.5rem;
	margin: 35px 0 15px 0;
	color: var(--primary-color);
}

/* Blockquote Formatting */
.article-body blockquote {
	background-color: #f9f9f9;
	border-left: 4px solid var(--primary-color);
	margin: 30px 0;
	padding: 20px 25px;
	font-style: italic;
	color: #444444;
}

.article-body blockquote cite {
	display: block;
	font-style: normal;
	font-weight: 600;
	font-size: 0.9rem;
	margin-top: 10px;
	color: var(--secondary-color);
}

/* 9. Comments Section */
.comments-section {
	margin-top: 50px;
	border-top: 2px solid var(--border-color);
	padding-top: 35px;
}

.comments-section h3 {
	margin-bottom: 20px;
}

.comment-list {
	display: flex;
	flex-direction: column;
	gap: 20px;
	margin-bottom: 40px;
}

.comment-item {
	background: #fdfdfd;
	border: 1px solid var(--border-color);
	border-radius: 4px;
	padding: 20px;
}

.comment-meta {
	margin-bottom: 10px;
	font-size: 0.9rem;
}

.comment-author {
	font-weight: 700;
	color: var(--primary-color);
	margin-right: 10px;
}

.comment-date {
	color: var(--secondary-color);
}

.comment-content p {
	font-size: 1rem;
	color: #444444;
}

/* 10. Comment Interactive Input Fields */
.comment-form {
	background-color: #f9f9f9;
	padding: 25px;
	border-radius: 6px;
	border: 1px solid var(--border-color);
}

.form-group {
	margin-bottom: 15px;
	display: flex;
	flex-direction: column;
	gap: 5px;
}

.form-group label {
	font-size: 0.9rem;
	font-weight: 600;
	color: var(--primary-color);
}

.form-group input,
.form-group textarea {
	width: 100%;
	padding: 10px;
	border: 1px solid var(--border-color);
	border-radius: 4px;
	font-family: inherit;
	font-size: 1px;
}

.form-group input:focus,
.form-group textarea:focus {
	outline: none;
	border-color: var(--accent-color);
	box-shadow: 0 0 0 2px rgba(0, 102, 204, 0.1);
}

.submit-btn {
	background-color: var(--primary-color);
	color: #ffffff;
	border: none;
	padding: 12px 24px;
	font-size: 0.95rem;
	font-weight: 600;
	border-radius: 4px;
	cursor: pointer;
	transition: background-color 0.2s ease;
}

.submit-btn:hover {
	background-color: var(--accent-color);
}

/* Small adjustments for screens smaller than tablet */
@media (max-width: 600px) {
	.blog-content {
		padding: 20px;
	}
	.entry-title {
		font-size: 2rem;
	}
}

(() => {
	function calculateReadingTime(elementId, wpm = 225) {
		// 1. Grab the text from the target HTML element
		const element = document.getElementById(elementId);
		if (!element) return "0 min read";

		const text = element.innerText || element.textContent;

		// 2. Clean up whitespace and split by spaces to count words
		const words = text
			.trim()
			.split(/\s+/)
			.filter((word) => word.length > 0).length;

		// 3. Divide word count by WPM and round up
		const readingTime = Math.ceil(words / wpm);

		return `${readingTime} min read`;
	}

	if (typeof window !== undefined) {
		const title = document
			.getElementById("entry-title")
			.textContent.toLowerCase()
			.split(" ")
			.join("-");

		const metaSpan = document.getElementById("post-meta");
		const readingTime = calculateReadingTime("article-body");
		metaSpan.textContent = metaSpan.textContent + " • " + readingTime;
	}
})();

import { createRequire } from "module";
import fs from "fs";
const require = createRequire(import.meta.url);
const { collect } = require("./loc/bc");

const exts = collect.defaultFiles();

const files = collect.getFilePaths(".", exts, ["loc"]);
const fileObj = collect.initPageFiles(files, exts, "dist");

fs.writeFileSync("bb.json", JSON.stringify(fileObj, null, 2));
